def SharpRegionM37B (n : ℕ) (k : ℤ) (lo hi : ℕ) : Prop :=
 (n+2:ℝ)*((k:ℝ)*2-hi-lo+3)^2 ≤
   4*(n+1)*((k:ℝ)-hi+2)*((k:ℝ)-lo+2)

def DiagonalSharpM37B (a b i j : ℕ) : Prop :=
 ∃ r, i+j+2+r=a+b-1 ∧ 2*r ≤ a+b-1 ∧
   SharpRegionM37B (a+b-1-2*r) i 0 r

